sp_widget.client_script:
api.controller = function($location, $timeout) {

    var c = this;

    var DROPDOWN_LIMIT = 6;

    c.ddOpen = false;
    c.ddEl = null;
    c.ddHost = null;


    /* =========================================================
       INITIALIZATION
       ========================================================= */

    c.$onInit = function() {

        if (!c.data || !c.data.notifications) {
            c.data.notifications = [];
        }

        if (typeof c.data.unreadCount === 'undefined') {
            c.data.unreadCount = 0;
        }

        c.data.loading = false;


        /* Counters */

        c.applicationNotifications = 0;
        c.offerNotifications = 0;
        c.driveNotifications = 0;
        c.deadlineNotifications = 0;
        c.interviewNotifications = 0;
        c.placementNotifications = 0;

        c.applicationPercentage = 0;
        c.offerPercentage = 0;
        c.drivePercentage = 0;
        c.deadlinePercentage = 0;
        c.unreadPercentage = 0;

        c.calculateStatistics();


        /* Close dropdown on outside click / Escape / resize */

        document.addEventListener(
            'click',
            c.onDocumentClick
        );

        document.addEventListener(
            'keydown',
            c.onKeyDown
        );

        window.addEventListener(
            'resize',
            c.closeDropdown
        );


        /* Header renders separately */

        $timeout(
            c.updateHeaderBadge,
            300
        );

        $timeout(
            c.updateHeaderBadge,
            1000
        );

        $timeout(
            c.updateHeaderBadge,
            2500
        );

        $timeout(
            c.updateHeaderBadge,
            5000
        );
    };


    /* =========================================================
       DESTROY
       ========================================================= */

    c.$onDestroy = function() {

        document.removeEventListener(
            'click',
            c.onDocumentClick
        );

        document.removeEventListener(
            'keydown',
            c.onKeyDown
        );

        window.removeEventListener(
            'resize',
            c.closeDropdown
        );

        c.closeDropdown();
    };


    /* =========================================================
       HEADER BELL
       ========================================================= */

    c.getBellHosts = function() {

        var hosts = [];

        var icons = document.querySelectorAll(
            '.fa-bell, .fa-bell-o, .glyphicon-bell, [class*="icon-bell"]'
        );

        angular.forEach(
            icons,
            function(icon) {

                if (
                    icon.closest &&
                    (
                        icon.closest(
                            '.nx-notification-center'
                        ) ||
                        icon.closest(
                            '.nx-dd-panel'
                        )
                    )
                ) {
                    return;
                }

                var host =
                    (
                        icon.closest &&
                        icon.closest('a, button')
                    ) ||
                    icon.parentElement;

                if (
                    host &&
                    host !== document.body &&
                    hosts.indexOf(host) < 0
                ) {

                    hosts.push(host);
                }
            }
        );

        return hosts;
    };


    /* =========================================================
       HEADER BADGE
       ========================================================= */

    c.updateHeaderBadge = function() {

        try {

            var count =
                parseInt(
                    c.data.unreadCount,
                    10
                ) || 0;


            angular.forEach(
                c.getBellHosts(),
                function(host) {

                    if (
                        window.getComputedStyle(
                            host
                        ).position === 'static'
                    ) {

                        host.style.position =
                            'relative';
                    }

                    host.style.overflow =
                        'visible';


                    /* Badge */

                    var badge = null;

                    for (
                        var k = 0;
                        k < host.children.length;
                        k++
                    ) {

                        if (
                            host.children[k].className ===
                                'nx-header-bell-badge' ||

                            host.children[k].className ===
                                'nx-header-bell-badge nx-badge-hidden'
                        ) {

                            badge =
                                host.children[k];

                            break;
                        }
                    }


                    if (!badge) {

                        badge =
                            document.createElement(
                                'span'
                            );

                        badge.className =
                            'nx-header-bell-badge';

                        host.appendChild(
                            badge
                        );
                    }


                    badge.textContent =
                        count > 99
                            ? '99+'
                            : String(count);


                    if (count > 0) {

                        badge.classList.remove(
                            'nx-badge-hidden'
                        );

                    } else {

                        badge.classList.add(
                            'nx-badge-hidden'
                        );
                    }


                    /* Click -> dropdown */

                    if (
                        !host.getAttribute(
                            'data-nx-bell'
                        )
                    ) {

                        host.setAttribute(
                            'data-nx-bell',
                            '1'
                        );

                        host.addEventListener(
                            'click',
                            function(e) {

                                e.preventDefault();

                                e.stopPropagation();

                                c.toggleDropdown(
                                    host
                                );
                            },
                            true
                        );
                    }
                }
            );


            if (c.ddOpen) {
                c.renderDropdown();
            }

        } catch (err) {}
    };


    /* =========================================================
       DROPDOWN
       ========================================================= */

    c.toggleDropdown = function(host) {

        if (c.ddOpen) {

            c.closeDropdown();

            return;
        }

        c.ddHost = host;
        c.ddOpen = true;

        c.renderDropdown();
    };


    c.closeDropdown = function() {

        c.ddOpen = false;

        if (
            c.ddEl &&
            c.ddEl.parentNode
        ) {

            c.ddEl.parentNode.removeChild(
                c.ddEl
            );
        }

        c.ddEl = null;
    };


    c.onDocumentClick = function(e) {

        if (!c.ddOpen) {
            return;
        }

        if (
            c.ddEl &&
            c.ddEl.contains(e.target)
        ) {
            return;
        }

        c.closeDropdown();
    };


    c.onKeyDown = function(e) {

        if (
            c.ddOpen &&
            (
                e.key === 'Escape' ||
                e.keyCode === 27
            )
        ) {

            c.closeDropdown();
        }
    };


    /* =========================================================
       RENDER DROPDOWN
       ========================================================= */

    c.renderDropdown = function() {

        if (
            !c.ddOpen ||
            !c.ddHost
        ) {
            return;
        }


        if (
            c.ddEl &&
            c.ddEl.parentNode
        ) {

            c.ddEl.parentNode.removeChild(
                c.ddEl
            );
        }


        var notifications =
            c.data.notifications || [];

        var unread =
            parseInt(
                c.data.unreadCount,
                10
            ) || 0;


        var panel =
            document.createElement(
                'div'
            );

        panel.className =
            'nx-dd-panel';


        /* Header */

        var head =
            document.createElement(
                'div'
            );

        head.className =
            'nx-dd-head';


        var title =
            document.createElement(
                'span'
            );

        title.className =
            'nx-dd-title';

        title.textContent =
            'Recent Notifications';

        head.appendChild(title);


        if (unread > 0) {

            var cnt =
                document.createElement(
                    'span'
                );

            cnt.className =
                'nx-dd-count';

            cnt.textContent =
                unread + ' new';

            head.appendChild(cnt);
        }


        panel.appendChild(head);


        /* List */

        var list =
            document.createElement(
                'div'
            );

        list.className =
            'nx-dd-list';


        if (
            notifications.length === 0
        ) {

            var empty =
                document.createElement(
                    'div'
                );

            empty.className =
                'nx-dd-empty';

            empty.textContent =
                'You are all caught up.';

            list.appendChild(empty);

        } else {

            angular.forEach(
                notifications.slice(
                    0,
                    DROPDOWN_LIMIT
                ),
                function(n) {

                    list.appendChild(
                        c.buildDropdownItem(n)
                    );
                }
            );
        }


        panel.appendChild(list);


        /* Footer */

        var foot =
            document.createElement(
                'div'
            );

        foot.className =
            'nx-dd-foot';

        foot.textContent =
            'Showing ' +
            Math.min(
                DROPDOWN_LIMIT,
                notifications.length
            ) +
            ' of ' +
            notifications.length +
            ' updates';

        panel.appendChild(foot);


        document.body.appendChild(
            panel
        );

        c.ddEl = panel;


        /* Position */

        var rect =
            c.ddHost.getBoundingClientRect();

        panel.style.top =
            (rect.bottom + 10) + 'px';

        panel.style.right =
            Math.max(
                12,
                window.innerWidth -
                rect.right
            ) + 'px';
    };


    /* =========================================================
       DROPDOWN ITEM
       ========================================================= */

    c.buildDropdownItem = function(n) {

        var item =
            document.createElement(
                'div'
            );

        item.className =
            'nx-dd-item' +
            (
                n.unread
                    ? ' nx-dd-unread'
                    : ''
            );


        /* Icon */

        var icon =
            document.createElement(
                'div'
            );

        icon.className =
            'nx-dd-icon nx-type-' +
            c.getNotificationType(n);


        var i =
            document.createElement(
                'i'
            );

        i.className =
            'fa ' +
            c.getNotificationIcon(n);

        icon.appendChild(i);

        item.appendChild(icon);


        /* Body */

        var body =
            document.createElement(
                'div'
            );

        body.className =
            'nx-dd-body';


        var t =
            document.createElement(
                'div'
            );

        t.className =
            'nx-dd-item-title';


        if (n.unread) {

            var dot =
                document.createElement(
                    'span'
                );

            dot.className =
                'nx-dd-dot';

            t.appendChild(dot);
        }


        var tText =
            document.createElement(
                'span'
            );

        tText.textContent =
            n.title ||
            'Notification';

        t.appendChild(tText);

        body.appendChild(t);


        var msg =
            document.createElement(
                'div'
            );

        msg.className =
            'nx-dd-msg';

        msg.textContent =
            n.message || '';

        body.appendChild(msg);


        var meta =
            document.createElement(
                'div'
            );

        meta.className =
            'nx-dd-meta';

        meta.textContent =
            (
                n.date || ''
            ) +
            (
                n.company
                    ? '  |  ' + n.company
                    : ''
            );

        body.appendChild(meta);

        item.appendChild(body);


        /* Click */

        item.addEventListener(
            'click',
            function() {

                c.closeDropdown();


                /*
                 * Offer approval and Skill Request
                 * actions are handled from the
                 * notification action buttons.
                 */

                if (n.canDecide) {
                    return;
                }


                $timeout(
                    function() {

                        c.handleNotificationClick(
                            n
                        );
                    }
                );
            }
        );


        return item;
    };


    /* =========================================================
       STATISTICS
       ========================================================= */

    c.calculateStatistics = function() {

        var notifications =
            c.data.notifications || [];


        c.applicationNotifications = 0;
        c.offerNotifications = 0;
        c.driveNotifications = 0;
        c.deadlineNotifications = 0;
        c.interviewNotifications = 0;


        angular.forEach(
            notifications,
            function(notification) {

                if (!notification) {
                    return;
                }


                var type =
                    (
                        notification.type ||
                        'info'
                    ).toLowerCase();


                /* Applications */

                if (
                    type === 'application' ||
                    type === 'info' ||
                    type === 'success' ||
                    type === 'rejected' ||
                    type === 'application_new' ||
                    type === 'admin_application'
                ) {

                    c.applicationNotifications++;
                }


                /* Offers */

                if (
                    type === 'offer' ||
                    type === 'interviewer_offer' ||
                    type === 'offer_approval'
                ) {

                    c.offerNotifications++;
                }


                /* Drives */

                if (
                    type === 'drive' ||
                    type === 'admin_drive'
                ) {

                    c.driveNotifications++;
                }


                /* Deadlines */

                if (
                    type === 'deadline'
                ) {

                    c.deadlineNotifications++;
                }


                /* Interviews */

                if (
                    type === 'interview' ||
                    type === 'interview_assigned' ||
                    type === 'interview_pending' ||
                    type === 'feedback_pending'
                ) {

                    c.interviewNotifications++;
                }

            }
        );


        c.placementNotifications =
            c.offerNotifications +
            c.driveNotifications +
            c.deadlineNotifications +
            c.interviewNotifications;


        var total =
            notifications.length;


        if (total === 0) {

            c.applicationPercentage = 0;
            c.offerPercentage = 0;
            c.drivePercentage = 0;
            c.deadlinePercentage = 0;

        } else {

            c.applicationPercentage =
                Math.round(
                    (
                        c.applicationNotifications /
                        total
                    ) * 100
                );

            c.offerPercentage =
                Math.round(
                    (
                        c.offerNotifications /
                        total
                    ) * 100
                );

            c.drivePercentage =
                Math.round(
                    (
                        c.driveNotifications /
                        total
                    ) * 100
                );

            c.deadlinePercentage =
                Math.round(
                    (
                        c.deadlineNotifications /
                        total
                    ) * 100
                );
        }


        if (total > 0) {

            c.unreadPercentage =
                Math.round(
                    (
                        c.data.unreadCount /
                        total
                    ) * 100
                );

        } else {

            c.unreadPercentage = 0;
        }


        if (
            c.unreadPercentage > 100
        ) {

            c.unreadPercentage = 100;
        }
    };


    /* =========================================================
       NOTIFICATION TYPE
       ========================================================= */

    c.getNotificationType = function(
        notification
    ) {

        if (
            !notification ||
            !notification.type
        ) {

            return 'info';
        }

        return notification.type;
    };


    /* =========================================================
       NOTIFICATION LABEL
       ========================================================= */

    c.getNotificationLabel = function(
        notification
    ) {

        if (!notification) {
            return 'Update';
        }


        switch (
            (
                notification.type ||
                'info'
            ).toLowerCase()
        ) {

            case 'success':
                return 'Success';

            case 'offer':
                return 'Offer';

            case 'offer_approval':
                return 'Offer Approval';

            case 'drive':
                return 'Drive';

            case 'admin_drive':
                return 'Drive';

            case 'deadline':
                return 'Deadline';

            case 'rejected':
                return 'Update';

            case 'info':
                return 'Application';

            case 'application':
                return 'Application';

            case 'application_new':
                return 'Application';

            case 'admin_application':
                return 'Application';

            case 'interview':
                return 'Interview';

            case 'interview_pending':
                return 'Attention';

            case 'feedback_pending':
                return 'Feedback';

            case 'interview_assigned':
                return 'Interview';

            case 'skill_request':
                return 'Skill Request';

            default:
                return 'Update';
        }
    };


    /* =========================================================
       NOTIFICATION ICON
       ========================================================= */

    c.getNotificationIcon = function(
        notification
    ) {

        if (!notification) {
            return 'fa-info';
        }


        switch (
            (
                notification.type ||
                'info'
            ).toLowerCase()
        ) {

            case 'success':
                return 'fa-check';

            case 'offer':
                return 'fa-file-text-o';

            case 'offer_approval':
                return 'fa-file-text-o';

            case 'drive':
            case 'admin_drive':
                return 'fa-calendar';

            case 'deadline':
                return 'fa-clock-o';

            case 'rejected':
                return 'fa-times';

            case 'application':
            case 'application_new':
            case 'admin_application':
                return 'fa-file-text-o';

            case 'interview':
            case 'interview_assigned':
                return 'fa-calendar-check-o';

            case 'interview_pending':
                return 'fa-exclamation';

            case 'feedback_pending':
                return 'fa-pencil-square-o';

            case 'skill_request':
                return 'fa-code';

            default:
                return 'fa-info';
        }
    };


    /* =========================================================
       OPEN NOTIFICATION
       ========================================================= */

    c.openNotification = function(
        notification
    ) {

        if (
            !notification ||
            !notification.link
        ) {
            return;
        }

        $location.url(
            notification.link
        );
    };


    /* =========================================================
       MARK AS READ
       ========================================================= */

    c.markAsRead = function(
        notification
    ) {

        if (
            !notification ||
            !notification.unread
        ) {
            return;
        }


        notification.unread = false;


        if (
            c.data.unreadCount > 0
        ) {

            c.data.unreadCount--;
        }


        c.calculateStatistics();

        $timeout(
            c.updateHeaderBadge,
            0
        );
    };


    /* =========================================================
       HANDLE NORMAL NOTIFICATION CLICK
       ========================================================= */

    c.handleNotificationClick = function(
        notification
    ) {

        if (!notification) {
            return;
        }


        /*
         * Skill Requests do NOT navigate.
         */

        if (
            notification.type ===
            'skill_request'
        ) {

            if (
                notification.unread
            ) {

                c.markAsRead(
                    notification
                );
            }

            return;
        }


        if (
            notification.unread
        ) {

            c.markAsRead(
                notification
            );
        }


        if (
            notification.link
        ) {

            c.openNotification(
                notification
            );
        }
    };


    /* =========================================================
       OFFER LETTER ACCEPT / REJECT
       EXISTING FUNCTIONALITY
       ========================================================= */

    c.decideOffer = function(
        notification,
        decision,
        $event
    ) {

        if ($event) {
            $event.stopPropagation();
        }


        if (
            !notification ||
            !notification.approvalId ||
            notification.decision !==
                'pending'
        ) {
            return;
        }


        if (
            notification.processing
        ) {
            return;
        }


        notification.processing = true;


        c.server.get({

            action:
                'offer_decision',

            approvalId:
                notification.approvalId,

            decision:
                decision

        }).then(

            function(response) {

                notification.processing =
                    false;


                if (
                    response &&
                    response.data &&
                    response.data.actionSuccess
                ) {

                    notification.decision =
                        response.data.actionDecision;

                    notification.canDecide =
                        false;

                    notification.unread =
                        false;


                    if (
                        c.data.unreadCount > 0
                    ) {

                        c.data.unreadCount--;
                    }


                    c.calculateStatistics();

                    $timeout(
                        c.updateHeaderBadge,
                        0
                    );

                } else {

                    alert(

                        (
                            response &&
                            response.data &&
                            response.data.actionMessage
                        ) ||
                        'Unable to process the offer.'
                    );
                }

            },

            function() {

                notification.processing =
                    false;

                alert(
                    'Unable to process the offer.'
                );
            }
        );
    };


    /* =========================================================
       SKILL REQUEST
       ACCEPT / REJECT / MAP EXISTING
       ========================================================= */

    c.decideSkillRequest = function(
        notification,
        decision,
        matchedSkillId,
        $event
    ) {

        if ($event) {
            $event.stopPropagation();
        }


        if (
            !notification ||
            notification.type !==
                'skill_request'
        ) {
            return;
        }


        if (
            !notification.skillRequestId
        ) {
            return;
        }


        if (
            notification.skillRequestDecision !==
                'pending'
        ) {
            return;
        }


        if (
            notification.processing
        ) {
            return;
        }


        /*
         * MAP EXISTING button:
         * First click opens the selector.
         */

        if (
            decision === 'merged' &&
            !matchedSkillId
        ) {

            notification.showSkillMap =
                true;

            return;
        }


        /*
         * For merged action, an existing
         * skill must be selected.
         */

        if (
            decision === 'merged' &&
            !matchedSkillId
        ) {

            alert(
                'Please select an existing skill.'
            );

            return;
        }


        notification.processing =
            true;


        c.server.get({

            action:
                'skill_request_decision',

            skillRequestId:
                notification.skillRequestId,

            decision:
                decision,

            matchedSkillId:
                matchedSkillId || ''

        }).then(

            function(response) {

                notification.processing =
                    false;


                if (
                    response &&
                    response.data &&
                    response.data.actionSuccess
                ) {

                    notification.skillRequestDecision =
                        response.data.actionDecision;

                    notification.canDecide =
                        false;

                    notification.showSkillMap =
                        false;

                    notification.unread =
                        false;


                    if (
                        c.data.unreadCount > 0
                    ) {

                        c.data.unreadCount--;
                    }


                    c.calculateStatistics();


                    $timeout(
                        c.updateHeaderBadge,
                        0
                    );

                } else {

                    alert(

                        (
                            response &&
                            response.data &&
                            response.data.actionMessage
                        ) ||
                        'Unable to process the skill request.'
                    );
                }

            },

            function() {

                notification.processing =
                    false;

                alert(
                    'Unable to process the skill request.'
                );
            }
        );
    };


    /* =========================================================
       END
       ========================================================= */

};

sp_widget.css:
/* =========================================================
   NEXORA NOTIFICATION CENTER
   ========================================================= */

.nx-notification-center {
    width: 100%;
    max-width: 1400px;
    margin: 0 auto;
    padding: 30px;
    box-sizing: border-box;
    background: #ffffff;
}


/* =========================================================
   HERO
   ========================================================= */

.nx-notification-hero {
    display: flex;
    justify-content: space-between;
    align-items: center;

    padding: 32px 36px;

    border-radius: 18px;

    background:
        linear-gradient(
            135deg,
            #0b2745,
            #143f69
        );

    color: #ffffff;

    margin-bottom: 28px;

    box-shadow:
        0 12px 35px rgba(16, 42, 67, 0.12);
}


.nx-hero-left {
    flex: 1;
}


.nx-page-kicker {
    display: flex;
    align-items: center;

    gap: 8px;

    font-size: 11px;
    font-weight: 800;

    letter-spacing: 1.5px;

    color: #ff7568;

    margin-bottom: 10px;
}


.nx-kicker-dot {
    width: 7px;
    height: 7px;

    border-radius: 50%;

    background: #ff7568;
}


.nx-notification-hero h1 {
    margin: 0;

    font-size: 30px;

    font-weight: 800;

    letter-spacing: -0.5px;
}


.nx-notification-hero p {
    margin: 9px 0 0;

    font-size: 14px;

    color: rgba(255,255,255,0.78);
}


/* =========================================================
   HERO STATUS
   ========================================================= */

.nx-hero-status {
    display: flex;

    align-items: center;

    gap: 14px;

    padding: 14px 18px;

    border-radius: 14px;

    background: rgba(255,255,255,0.08);

    border: 1px solid rgba(255,255,255,0.12);
}


.nx-status-icon {
    width: 46px;
    height: 46px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 12px;

    background: rgba(255,255,255,0.10);

    color: #ff7568;

    font-size: 20px;
}


.nx-status-content {
    display: flex;

    flex-direction: column;

    gap: 4px;
}


.nx-status-content span {
    font-size: 9px;

    letter-spacing: 1px;

    font-weight: 700;

    color: rgba(255,255,255,0.55);
}


.nx-status-content strong {
    font-size: 14px;

    color: #ffffff;
}


/* =========================================================
   OVERVIEW GRID
   ========================================================= */

.nx-overview-grid {
    display: grid;

    grid-template-columns:
        repeat(4, 1fr);

    gap: 18px;

    margin-bottom: 24px;
}


.nx-overview-card {
    display: flex;

    align-items: center;

    gap: 15px;

    padding: 20px;

    background: #ffffff;

    border: 1px solid #e3eaf1;

    border-radius: 14px;

    box-shadow:
        0 5px 18px rgba(16,42,67,0.05);
}


.nx-overview-icon {
    width: 48px;
    height: 48px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 12px;

    font-size: 18px;
}


.nx-icon-navy {
    background: #edf3f8;
    color: #102a43;
}


.nx-icon-coral {
    background: #fff0ed;
    color: #ff6f61;
}


.nx-icon-blue {
    background: #edf5ff;
    color: #3677b8;
}


.nx-icon-green {
    background: #edf9f2;
    color: #279365;
}


.nx-overview-info {
    display: flex;

    flex-direction: column;

    gap: 3px;
}


.nx-overview-info span {
    font-size: 10px;

    font-weight: 800;

    color: #718096;

    letter-spacing: 0.8px;
}


.nx-overview-info strong {
    font-size: 24px;

    color: #102a43;
}


.nx-overview-info small {
    font-size: 11px;

    color: #8492a6;
}


/* =========================================================
   ACTIVITY SECTION
   ========================================================= */

.nx-activity-section {
    display: grid;

    grid-template-columns:
        minmax(0, 2fr)
        minmax(280px, 1fr);

    gap: 20px;

    margin-bottom: 24px;
}


.nx-activity-card,
.nx-attention-card {
    border-radius: 16px;

    border: 1px solid #e3eaf1;

    background: #ffffff;

    box-shadow:
        0 5px 18px rgba(16,42,67,0.05);
}


.nx-activity-card {
    padding: 25px;
}


.nx-section-header {
    display: flex;

    justify-content: space-between;

    align-items: center;

    margin-bottom: 25px;
}


.nx-section-label {
    font-size: 10px;

    font-weight: 800;

    letter-spacing: 1.3px;

    color: #ff6f61;
}


.nx-section-header h2 {
    margin: 5px 0;

    font-size: 22px;

    color: #102a43;
}


.nx-section-header p {
    margin: 0;

    font-size: 12px;

    color: #7b8794;
}


.nx-activity-total {
    text-align: right;
}


.nx-activity-total strong {
    display: block;

    font-size: 28px;

    color: #102a43;
}


.nx-activity-total span {
    font-size: 11px;

    color: #8492a6;
}


/* =========================================================
   VISUALIZATION
   ========================================================= */

.nx-visualization {
    display: flex;

    flex-direction: column;

    gap: 16px;
}


.nx-visual-row {
    display: grid;

    grid-template-columns:
        150px
        1fr
        35px;

    align-items: center;

    gap: 15px;
}


.nx-visual-label {
    display: flex;

    align-items: center;

    gap: 8px;

    font-size: 12px;

    color: #52606d;
}


.nx-visual-dot {
    width: 8px;
    height: 8px;

    border-radius: 50%;
}


.nx-dot-info {
    background: #4d8bc4;
}


.nx-dot-offer {
    background: #36a269;
}


.nx-dot-drive {
    background: #5d6fc4;
}


.nx-dot-deadline {
    background: #ef9c43;
}


.nx-visual-track {
    height: 8px;

    border-radius: 20px;

    background: #edf1f5;

    overflow: hidden;
}


.nx-visual-fill {
    height: 100%;

    min-width: 2px;

    border-radius: 20px;

    transition:
        width 0.4s ease;
}


.nx-fill-info {
    background: #4d8bc4;
}


.nx-fill-offer {
    background: #36a269;
}


.nx-fill-drive {
    background: #5d6fc4;
}


.nx-fill-deadline {
    background: #ef9c43;
}


.nx-visual-row > strong {
    text-align: right;

    font-size: 12px;

    color: #102a43;
}


/* =========================================================
   ATTENTION CARD
   ========================================================= */

.nx-attention-card {
    padding: 25px;

    background:
        linear-gradient(
            145deg,
            #102a43,
            #173f63
        );

    color: #ffffff;

    border: none;
}


.nx-attention-top {
    display: flex;

    align-items: center;

    gap: 10px;
}


.nx-attention-icon {
    width: 36px;
    height: 36px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 10px;

    background: rgba(255,255,255,0.10);

    color: #ff7568;
}


.nx-attention-top span {
    font-size: 10px;

    font-weight: 800;

    letter-spacing: 1px;
}


.nx-attention-number {
    margin-top: 25px;

    font-size: 45px;

    font-weight: 800;
}


.nx-attention-card h3 {
    margin: 0;

    font-size: 18px;
}


.nx-attention-card p {
    margin: 8px 0 20px;

    font-size: 12px;

    line-height: 1.6;

    color: rgba(255,255,255,0.70);
}


.nx-attention-progress {
    height: 7px;

    border-radius: 20px;

    background: rgba(255,255,255,0.12);

    overflow: hidden;
}


.nx-attention-progress-bar {
    height: 100%;

    background: #ff7568;

    border-radius: 20px;
}


.nx-attention-footer {
    display: flex;

    justify-content: space-between;

    margin-top: 12px;

    font-size: 11px;

    color: rgba(255,255,255,0.65);
}


/* =========================================================
   FEED
   ========================================================= */

.nx-feed-card {
    background: #ffffff;

    border: 1px solid #e3eaf1;

    border-radius: 16px;

    box-shadow:
        0 5px 18px rgba(16,42,67,0.05);

    overflow: hidden;
}


.nx-feed-header {
    display: flex;

    align-items: center;

    justify-content: space-between;

    padding: 22px 25px;

    border-bottom: 1px solid #edf1f5;
}


.nx-feed-title {
    display: flex;

    align-items: center;

    gap: 12px;
}


.nx-feed-icon {
    width: 42px;
    height: 42px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 11px;

    background: #edf3f8;

    color: #102a43;
}


.nx-feed-title span {
    font-size: 9px;

    font-weight: 800;

    letter-spacing: 1px;

    color: #8492a6;
}


.nx-feed-title h2 {
    margin: 3px 0 0;

    font-size: 19px;

    color: #102a43;
}


.nx-feed-count {
    display: flex;

    gap: 5px;

    align-items: center;

    font-size: 11px;

    color: #8492a6;
}


.nx-feed-count strong {
    color: #102a43;
}


/* =========================================================
   FEED ITEM
   ========================================================= */

.nx-feed-list {
    width: 100%;
}


.nx-feed-item {
    position: relative;

    display: grid;

    grid-template-columns:
        50px
        minmax(0, 1fr)
        100px;

    gap: 15px;

    padding: 22px 25px;

    border-bottom: 1px solid #edf1f5;

    transition:
        background 0.2s ease;
}


.nx-feed-item:hover {
    background: #fafcfe;
}


.nx-feed-unread {
    background: #f8fbff;
}


.nx-feed-unread:hover {
    background: #f4f9fd;
}


/* =========================================================
   TIMELINE
   ========================================================= */

.nx-timeline {
    position: relative;

    display: flex;

    justify-content: center;
}


.nx-timeline-icon {
    position: relative;

    z-index: 2;

    width: 38px;
    height: 38px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 11px;

    font-size: 14px;
}


.nx-timeline-line {
    position: absolute;

    top: 38px;

    bottom: -22px;

    width: 1px;

    background: #e2e8ee;
}


.nx-feed-item:last-child
.nx-timeline-line {
    display: none;
}


/* =========================================================
   TYPE COLORS
   ========================================================= */

.nx-type-info,
.nx-type-application_new,
.nx-type-admin_application {
    background: #edf5ff;
    color: #3677b8;
}


.nx-type-success {
    background: #edf9f2;
    color: #279365;
}


.nx-type-offer {
    background: #edf9f2;
    color: #279365;
}


.nx-type-drive,
.nx-type-admin_drive {
    background: #f0f2ff;
    color: #5d6fc4;
}


.nx-type-deadline {
    background: #fff5e8;
    color: #e2913a;
}


.nx-type-rejected {
    background: #fff0ed;
    color: #e45c4d;
}


.nx-type-interview_pending,
.nx-type-feedback_pending {
    background: #fff5e8;
    color: #df8d30;
}


.nx-type-interview_assigned {
    background: #edf5ff;
    color: #3677b8;
}


/* =========================================================
   SKILL REQUEST TYPE
   ========================================================= */

.nx-type-skill_request {
    background: #edf5ff;
    color: #3677b8;
}


/* =========================================================
   CONTENT
   ========================================================= */

.nx-feed-content {
    min-width: 0;
}


.nx-feed-top {
    display: flex;

    justify-content: space-between;

    align-items: flex-start;

    gap: 15px;
}


.nx-feed-heading {
    display: flex;

    align-items: center;

    gap: 8px;
}


.nx-feed-heading h3 {
    margin: 0;

    font-size: 14px;

    font-weight: 750;

    color: #102a43;
}


.nx-new-label {
    padding: 3px 7px;

    border-radius: 20px;

    background: #ff6f61;

    color: #ffffff;

    font-size: 8px;

    font-weight: 800;

    letter-spacing: 0.5px;
}


.nx-feed-date {
    white-space: nowrap;

    font-size: 10px;

    color: #8a9aad;
}


.nx-feed-date i {
    margin-right: 4px;
}


.nx-feed-message {
    margin: 8px 0;

    font-size: 12px;

    line-height: 1.6;

    color: #52606d;
}


/* =========================================================
   META
   ========================================================= */

.nx-feed-meta {
    display: flex;

    flex-wrap: wrap;

    gap: 8px;

    align-items: center;

    margin-top: 8px;

    font-size: 10px;

    color: #718096;
}


.nx-feed-meta i {
    margin-right: 4px;

    color: #9aa9b8;
}


.nx-meta-divider {
    color: #c2ccd6;
}


/* =========================================================
   ACTION
   ========================================================= */

.nx-feed-action {
    margin-top: 13px;
}


.nx-feed-button {
    display: inline-flex;

    align-items: center;

    gap: 7px;

    padding: 8px 12px;

    border-radius: 8px;

    border: 1px solid #dce5ed;

    background: #ffffff;

    color: #173b5c;

    font-size: 10px;

    font-weight: 700;

    text-decoration: none;

    transition:
        all 0.2s ease;
}


.nx-feed-button:hover {
    text-decoration: none;

    background: #102a43;

    color: #ffffff;

    border-color: #102a43;
}


/* =========================================================
   STATUS
   ========================================================= */

.nx-feed-status {
    display: flex;

    align-items: flex-end;

    flex-direction: column;

    gap: 12px;
}


.nx-status-pill {
    display: inline-flex;

    align-items: center;

    justify-content: center;

    padding: 6px 10px;

    border-radius: 20px;

    font-size: 9px;

    font-weight: 800;

    white-space: nowrap;
}


.nx-pill-info,
.nx-pill-application_new,
.nx-pill-admin_application {
    background: #edf5ff;
    color: #3677b8;
}


.nx-pill-success {
    background: #edf9f2;
    color: #279365;
}


.nx-pill-offer {
    background: #edf9f2;
    color: #279365;
}


.nx-pill-drive,
.nx-pill-admin_drive {
    background: #f0f2ff;
    color: #5d6fc4;
}


.nx-pill-deadline {
    background: #fff5e8;
    color: #e2913a;
}


.nx-pill-rejected {
    background: #fff0ed;
    color: #e45c4d;
}


.nx-pill-interview_pending,
.nx-pill-feedback_pending {
    background: #fff5e8;
    color: #df8d30;
}


.nx-pill-interview_assigned {
    background: #edf5ff;
    color: #3677b8;
}


/* =========================================================
   SKILL REQUEST STATUS PILL
   ========================================================= */

.nx-pill-skill_request {
    background: #edf5ff;

    color: #3677b8;
}


.nx-unread-mark {
    width: 8px;
    height: 8px;

    border-radius: 50%;

    background: #ff6f61;
}


/* =========================================================
   SKILL REQUEST ACTIONS
   ========================================================= */

.nx-skill-request-actions {
    display: flex;

    align-items: center;

    flex-wrap: wrap;

    gap: 8px;

    margin-top: 13px;
}


/* =========================================================
   COMMON SKILL REQUEST BUTTON
   ========================================================= */

.nx-skill-request-actions button {
    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 6px;

    padding: 8px 12px;

    border-radius: 8px;

    font-size: 10px;

    font-weight: 700;

    cursor: pointer;

    white-space: nowrap;

    transition:
        background 0.2s ease,
        border-color 0.2s ease,
        color 0.2s ease,
        transform 0.15s ease;
}


.nx-skill-request-actions button:disabled {
    opacity: 0.55;

    cursor: not-allowed;

    transform: none;
}


.nx-skill-request-actions button:not(:disabled):active {
    transform: translateY(1px);
}


/* =========================================================
   SKILL ACCEPT
   ========================================================= */

.nx-skill-accept {
    background: #edf9f2;

    color: #279365;

    border: 1px solid #ccebd9;
}


.nx-skill-accept:hover:not(:disabled) {
    background: #279365;

    color: #ffffff;

    border-color: #279365;
}


/* =========================================================
   SKILL REJECT
   ========================================================= */

.nx-skill-reject {
    background: #fff0ed;

    color: #e45c4d;

    border: 1px solid #f4d0ca;
}


.nx-skill-reject:hover:not(:disabled) {
    background: #e45c4d;

    color: #ffffff;

    border-color: #e45c4d;
}


/* =========================================================
   MAP EXISTING
   ========================================================= */

.nx-skill-map {
    background: #edf5ff;

    color: #3677b8;

    border: 1px solid #d2e4f7;
}


.nx-skill-map:hover:not(:disabled) {
    background: #3677b8;

    color: #ffffff;

    border-color: #3677b8;
}


/* =========================================================
   MAP EXISTING SKILL BOX
   ========================================================= */

.nx-skill-map-box {
    display: flex;

    align-items: center;

    flex-wrap: wrap;

    gap: 8px;

    margin-top: 10px;

    padding: 10px;

    width: fit-content;

    max-width: 100%;

    border-radius: 9px;

    background: #f8fbfd;

    border: 1px solid #dce7ef;
}


/* =========================================================
   SKILL SELECT
   ========================================================= */

.nx-skill-select {
    min-width: 220px;

    height: 34px;

    padding: 0 10px;

    border-radius: 7px;

    border: 1px solid #d5e0e8;

    background: #ffffff;

    color: #52606d;

    font-size: 11px;

    outline: none;

    cursor: pointer;

    transition:
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}


.nx-skill-select:focus {
    border-color: #3677b8;

    box-shadow:
        0 0 0 3px rgba(54,119,184,0.10);
}


/* =========================================================
   MAP SKILL CONFIRM
   ========================================================= */

.nx-skill-map-confirm {
    display: inline-flex;

    align-items: center;

    justify-content: center;

    gap: 6px;

    height: 34px;

    padding: 0 12px;

    border-radius: 7px;

    border: 1px solid #3677b8;

    background: #3677b8;

    color: #ffffff;

    font-size: 10px;

    font-weight: 700;

    cursor: pointer;

    transition:
        background 0.2s ease,
        border-color 0.2s ease,
        opacity 0.2s ease;
}


.nx-skill-map-confirm:hover:not(:disabled) {
    background: #285f94;

    border-color: #285f94;
}


.nx-skill-map-confirm:disabled {
    opacity: 0.5;

    cursor: not-allowed;
}


/* =========================================================
   SKILL REQUEST RESULT
   ========================================================= */

.nx-skill-result {
    display: inline-flex;

    align-items: center;

    gap: 7px;

    margin-top: 13px;

    padding: 8px 12px;

    border-radius: 8px;

    font-size: 10px;

    font-weight: 700;
}


/* =========================================================
   APPROVED
   ========================================================= */

.nx-skill-approved {
    background: #edf9f2;

    color: #279365;

    border: 1px solid #ccebd9;
}


/* =========================================================
   REJECTED
   ========================================================= */

.nx-skill-rejected {
    background: #fff0ed;

    color: #e45c4d;

    border: 1px solid #f4d0ca;
}


/* =========================================================
   MAPPED
   ========================================================= */

.nx-skill-merged {
    background: #edf5ff;

    color: #3677b8;

    border: 1px solid #d2e4f7;
}


/* =========================================================
   EMPTY STATE
   ========================================================= */

.nx-feed-empty {
    text-align: center;

    padding: 70px 25px;
}


.nx-empty-ring {
    width: 70px;
    height: 70px;

    display: flex;

    align-items: center;
    justify-content: center;

    margin: 0 auto 18px;

    border-radius: 50%;

    background: #f2f6f9;

    color: #8a9aad;

    font-size: 25px;
}


.nx-feed-empty h3 {
    margin: 0 0 8px;

    color: #102a43;

    font-size: 18px;
}


.nx-feed-empty p {
    max-width: 480px;

    margin: auto;

    color: #8492a6;

    font-size: 12px;

    line-height: 1.7;
}


/* =========================================================
   INFORMATION STRIP
   ========================================================= */

.nx-info-strip {
    display: flex;

    align-items: center;

    gap: 14px;

    margin-top: 24px;

    padding: 16px 20px;

    border: 1px solid #e3eaf1;

    border-radius: 14px;

    background: #ffffff;

    box-shadow:
        0 5px 18px rgba(16,42,67,0.04);
}


.nx-info-strip-icon {
    width: 40px;
    height: 40px;

    flex-shrink: 0;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 10px;

    background: #edf3f8;

    color: #102a43;
}


.nx-info-strip-content {
    display: flex;

    flex-direction: column;

    gap: 4px;

    flex: 1;
}


.nx-info-strip-content strong {
    font-size: 12px;

    color: #102a43;
}


.nx-info-strip-content span {
    font-size: 10px;

    line-height: 1.5;

    color: #8492a6;
}


.nx-info-strip-status {
    display: flex;

    align-items: center;

    gap: 6px;

    white-space: nowrap;

    font-size: 10px;

    font-weight: 700;

    color: #279365;
}


.nx-live-dot {
    width: 7px;
    height: 7px;

    border-radius: 50%;

    background: #279365;
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1000px) {

    .nx-overview-grid {
        grid-template-columns:
            repeat(2, 1fr);
    }


    .nx-activity-section {
        grid-template-columns: 1fr;
    }

}


@media (max-width: 700px) {

    .nx-notification-center {
        padding: 15px;
    }


    .nx-notification-hero {
        flex-direction: column;

        align-items: flex-start;

        gap: 20px;
    }


    .nx-hero-status {
        width: 100%;

        box-sizing: border-box;
    }


    .nx-overview-grid {
        grid-template-columns: 1fr;
    }


    .nx-feed-item {
        grid-template-columns:
            40px
            minmax(0, 1fr);
    }


    .nx-feed-status {
        grid-column: 2;

        align-items: flex-start;
    }


    .nx-visual-row {
        grid-template-columns:
            120px
            1fr
            30px;
    }


    .nx-skill-request-actions {
        width: 100%;

        align-items: stretch;
    }


    .nx-skill-request-actions button {
        flex: 0 0 auto;
    }


    .nx-skill-map-box {
        width: 100%;

        box-sizing: border-box;
    }


    .nx-skill-select {
        min-width: 0;

        width: 100%;
    }


    .nx-skill-map-confirm {
        width: 100%;
    }


    .nx-info-strip {
        align-items: flex-start;

        flex-wrap: wrap;
    }


    .nx-info-strip-status {
        width: 100%;
    }

}

sp_widget.script:
(function () {

    /* =========================================================
       NEXORA NOTIFICATION CENTER
       Supports:
       1. Student
       2. Placement Admin
       3. Placement Officer
       4. Interviewer = Company HR

       Skill Request:
       - Placement Admin receives pending skill requests
       - Accept
       - Reject
       - Map Existing Skill
       ========================================================= */

    data.notifications = [];
    data.unreadCount = 0;
    data.error = '';
    data.loading = false;

    var USER_ID = gs.getUserID();

    if (!USER_ID) {
        data.error = 'Unable to identify logged-in user.';
        return;
    }


    /* =========================================================
       ROLES
       ========================================================= */

    var STUDENT_ROLE =
        'x_snc_college_pl_0.student';

    var ADMIN_ROLE =
        'x_snc_college_pl_0.placement_admin';

    var OFFICER_ROLE =
        'x_snc_college_pl_0.placement_officer';

    var INTERVIEWER_ROLE =
        'x_snc_college_pl_0.interviewer';


    /* =========================================================
       TABLES
       ========================================================= */

    var STUDENT_TABLE =
        'x_snc_college_pl_0_student';

    var APPLICATION_TABLE =
        'x_snc_college_pl_0_application';

    var DRIVE_TABLE =
        'x_snc_college_pl_0_placement_drive';

    var OFFER_TABLE =
        'x_snc_college_pl_0_offer_letter';

    var INTERVIEW_TABLE =
        'x_snc_college_pl_0_interview';

    var COMPANY_TABLE =
        'x_snc_college_pl_0_company';

    var OFFER_APPROVAL_TABLE =
        'x_snc_college_pl_0_offer_letter_approval';

    var SKILL_REQUEST_TABLE =
        'x_snc_college_pl_0_skill_request';

    var SKILL_CATALOG_TABLE =
        'x_snc_college_pl_0_skills_catalog';


    /* =========================================================
       ADD NOTIFICATION
       ========================================================= */

    function addNotification(
        id,
        type,
        title,
        message,
        date,
        company,
        driveName,
        unread,
        link,
        actionText,
        sortDate
    ) {

        data.notifications.push({

            id: id,

            type: type || 'info',

            title: title || 'Notification',

            message: message || '',

            date: date || '',

            company: company || '',

            driveName: driveName || '',

            unread: unread === true,

            link: link || '',

            actionText:
                actionText || 'View Details',

            sortDate: sortDate || ''

        });

        if (unread === true) {
            data.unreadCount++;
        }
    }


    /* =========================================================
       GET STUDENT NAME
       ========================================================= */

    function getStudentName(studentId) {

        if (!studentId) {
            return 'Student';
        }

        var studentGR =
            new GlideRecord(STUDENT_TABLE);

        if (!studentGR.get(studentId)) {
            return 'Student';
        }

        var name = '';

        if (studentGR.isValidField('user')) {

            name =
                studentGR.getDisplayValue('user') || '';

        }

        if (
            !name &&
            studentGR.isValidField('name')
        ) {

            name =
                studentGR.getDisplayValue('name') || '';

        }

        if (!name) {

            name =
                studentGR.getDisplayValue() || '';

        }

        return name || 'Student';
    }


    /* =========================================================
       GET APPLICATION DETAILS
       ========================================================= */

    function getApplicationDetails(applicationGR) {

        var result = {

            company: '',

            driveName: '',

            driveId: ''

        };

        if (!applicationGR) {
            return result;
        }

        var driveId =
            applicationGR.getValue('drive');

        if (!driveId) {
            return result;
        }

        var driveGR =
            new GlideRecord(DRIVE_TABLE);

        if (driveGR.get(driveId)) {

            result.company =
                driveGR.getDisplayValue('company') || '';

            result.driveName =
                driveGR.getDisplayValue('drive_name') || '';

            result.driveId =
                driveId;
        }

        return result;
    }


    /* =========================================================
       SORT NOTIFICATIONS
       ========================================================= */

    function sortNotifications() {

        data.notifications.sort(function (a, b) {

            if (a.unread && !b.unread) {
                return -1;
            }

            if (!a.unread && b.unread) {
                return 1;
            }

            var dateA =
                a.sortDate || '';

            var dateB =
                b.sortDate || '';

            if (dateA < dateB) {
                return 1;
            }

            if (dateA > dateB) {
                return -1;
            }

            return 0;
        });
    }


    /* =========================================================
       ROLE CHECK
       ========================================================= */

    var isAdmin =
        gs.hasRole(ADMIN_ROLE);

    var isOfficer =
        gs.hasRole(OFFICER_ROLE);

    var isInterviewer =
        gs.hasRole(INTERVIEWER_ROLE);


    /* =========================================================
       OFFER LETTER APPROVAL ACTION
       Company HR accepts or rejects an offer
       ========================================================= */

    if (
        input &&
        input.action === 'offer_decision'
    ) {

        var approvalId =
            input.approvalId;

        var decision =
            input.decision;

        if (
            decision !== 'accepted' &&
            decision !== 'rejected'
        ) {

            data.actionSuccess = false;

            data.actionMessage =
                'Invalid decision.';

            return;
        }

        if (!approvalId) {

            data.actionSuccess = false;

            data.actionMessage =
                'Approval record not found.';

            return;
        }

        var approvalActionGR =
            new GlideRecord(
                OFFER_APPROVAL_TABLE
            );

        if (
            !approvalActionGR.isValid() ||
            !approvalActionGR.get(approvalId)
        ) {

            data.actionSuccess = false;

            data.actionMessage =
                'Approval record not found.';

            return;
        }

        if (
            approvalActionGR.getValue('hr_user') !==
            USER_ID
        ) {

            data.actionSuccess = false;

            data.actionMessage =
                'You are not authorized to make this decision.';

            return;
        }

        if (
            approvalActionGR.getValue('decision') !==
            'pending'
        ) {

            data.actionSuccess = false;

            data.actionMessage =
                'This offer has already been processed.';

            return;
        }

        var approvalOfferId =
            approvalActionGR.getValue(
                'offer_letter'
            );

        if (!approvalOfferId) {

            data.actionSuccess = false;

            data.actionMessage =
                'Offer letter not found.';

            return;
        }

        var approvalOfferGR =
            new GlideRecord(OFFER_TABLE);

        if (
            !approvalOfferGR.get(
                approvalOfferId
            )
        ) {

            data.actionSuccess = false;

            data.actionMessage =
                'Offer letter not found.';

            return;
        }

        var approvalCompanyId =
            approvalOfferGR.getValue('company');

        if (!approvalCompanyId) {

            data.actionSuccess = false;

            data.actionMessage =
                'Company not found.';

            return;
        }

        var approvalCompanyGR =
            new GlideRecord(COMPANY_TABLE);

        if (
            !approvalCompanyGR.get(
                approvalCompanyId
            )
        ) {

            data.actionSuccess = false;

            data.actionMessage =
                'Company not found.';

            return;
        }

        if (
            approvalCompanyGR.getValue('hr_user') !==
            USER_ID
        ) {

            data.actionSuccess = false;

            data.actionMessage =
                'You are not authorized to make this decision.';

            return;
        }

        approvalActionGR.setValue(
            'decision',
            decision
        );

        approvalActionGR.update();

        data.actionSuccess = true;

        data.actionDecision =
            decision;

        data.actionApprovalId =
            approvalId;

        data.actionMessage =
            decision === 'accepted'
                ? 'Offer accepted successfully.'
                : 'Offer rejected successfully.';

        return;
    }


    /* =========================================================
       SKILL REQUEST ACTION
       ACCEPT / REJECT / MAP EXISTING
       ========================================================= */

    if (
        input &&
        input.action === 'skill_request_decision'
    ) {

        /* -----------------------------------------------------
           ONLY PLACEMENT ADMIN / TPO
           ----------------------------------------------------- */

        if (!isAdmin) {

            data.actionSuccess = false;

            data.actionMessage =
                'You are not authorized to process skill requests.';

            return;
        }


        var skillRequestId =
            input.skillRequestId;

        var skillDecision =
            input.decision;

        var matchedSkillId =
            input.matchedSkillId || '';


        /* -----------------------------------------------------
           VALID DECISIONS
           ----------------------------------------------------- */

        if (
            skillDecision !== 'approved' &&
            skillDecision !== 'rejected' &&
            skillDecision !== 'merged'
        ) {

            data.actionSuccess = false;

            data.actionMessage =
                'Invalid skill request decision.';

            return;
        }


        /* -----------------------------------------------------
           REQUEST ID
           ----------------------------------------------------- */

        if (!skillRequestId) {

            data.actionSuccess = false;

            data.actionMessage =
                'Skill request not found.';

            return;
        }


        /* -----------------------------------------------------
           LOAD REQUEST
           ----------------------------------------------------- */

        var skillRequestGR =
            new GlideRecord(
                SKILL_REQUEST_TABLE
            );

        if (
            !skillRequestGR.isValid() ||
            !skillRequestGR.get(skillRequestId)
        ) {

            data.actionSuccess = false;

            data.actionMessage =
                'Skill request not found.';

            return;
        }


        /* -----------------------------------------------------
           ONLY PENDING REQUESTS CAN BE PROCESSED
           ----------------------------------------------------- */

        var currentSkillStatus =
            skillRequestGR.getValue('status');

        if (
            currentSkillStatus !== 'pending'
        ) {

            data.actionSuccess = false;

            data.actionMessage =
                'This skill request has already been processed.';

            return;
        }


        /* =====================================================
           MAP EXISTING SKILL
           ===================================================== */

        if (
            skillDecision === 'merged'
        ) {

            if (!matchedSkillId) {

                data.actionSuccess = false;

                data.actionMessage =
                    'Please select an existing skill.';

                return;
            }


            /* -------------------------------------------------
               GET SELECTED SKILL
               ------------------------------------------------- */

            var matchedSkillGR =
                new GlideRecord(
                    SKILL_CATALOG_TABLE
                );

            if (
                !matchedSkillGR.isValid() ||
                !matchedSkillGR.get(
                    matchedSkillId
                )
            ) {

                data.actionSuccess = false;

                data.actionMessage =
                    'Selected skill was not found.';

                return;
            }


            /* -------------------------------------------------
               GET REQUESTING STUDENT
               ------------------------------------------------- */

            var mergedStudentId =
                skillRequestGR.getValue(
                    'requested_by'
                );

            if (!mergedStudentId) {

                data.actionSuccess = false;

                data.actionMessage =
                    'Requesting student was not found.';

                return;
            }


            var mergedStudentGR =
                new GlideRecord(
                    STUDENT_TABLE
                );

            if (
                !mergedStudentGR.get(
                    mergedStudentId
                )
            ) {

                data.actionSuccess = false;

                data.actionMessage =
                    'Requesting student was not found.';

                return;
            }


            /* -------------------------------------------------
               ADD EXISTING SKILL TO STUDENT
               WITHOUT DUPLICATE
               ------------------------------------------------- */

            var mergedCurrentSkills =
                mergedStudentGR.getValue(
                    'skills'
                ) || '';

            var mergedSkillArray =
                mergedCurrentSkills
                    ? mergedCurrentSkills.split(',')
                    : [];


            if (
                mergedSkillArray.indexOf(
                    matchedSkillId
                ) < 0
            ) {

                mergedSkillArray.push(
                    matchedSkillId
                );

            }


            mergedStudentGR.setValue(
                'skills',
                mergedSkillArray.join(',')
            );

            mergedStudentGR.update();


            /* -------------------------------------------------
               UPDATE REQUEST
               ------------------------------------------------- */

            if (
                skillRequestGR.isValidField(
                    'matched_skills'
                )
            ) {

                skillRequestGR.setValue(
                    'matched_skills',
                    matchedSkillId
                );

            }


            skillRequestGR.setValue(
                'status',
                'merged'
            );


            if (
                skillRequestGR.isValidField(
                    'reviewed_by'
                )
            ) {

                skillRequestGR.setValue(
                    'reviewed_by',
                    USER_ID
                );

            }


            skillRequestGR.update();


            data.actionSuccess = true;

            data.actionDecision =
                'merged';

            data.actionSkillRequestId =
                skillRequestId;

            data.actionMessage =
                'Skill mapped successfully and added to the student.';

            return;
        }


        /* =====================================================
           APPROVE
           ===================================================== */

        if (
            skillDecision === 'approved'
        ) {

            /* -------------------------------------------------
               GET REQUESTED SKILL NAME
               ------------------------------------------------- */

            var requestedSkillName =
                String(
                    skillRequestGR.getValue(
                        'requested_term'
                    ) || ''
                ).trim();


            if (!requestedSkillName) {

                data.actionSuccess = false;

                data.actionMessage =
                    'Requested skill name was not found.';

                return;
            }


            /* -------------------------------------------------
               GET REQUESTING STUDENT
               ------------------------------------------------- */

            var approvedStudentId =
                skillRequestGR.getValue(
                    'requested_by'
                );

            if (!approvedStudentId) {

                data.actionSuccess = false;

                data.actionMessage =
                    'Requesting student was not found.';

                return;
            }


            var approvedStudentGR =
                new GlideRecord(
                    STUDENT_TABLE
                );

            if (
                !approvedStudentGR.get(
                    approvedStudentId
                )
            ) {

                data.actionSuccess = false;

                data.actionMessage =
                    'Requesting student was not found.';

                return;
            }


            /* -------------------------------------------------
               CHECK SKILL CATALOG
               ------------------------------------------------- */

            var approvedSkillGR =
                new GlideRecord(
                    SKILL_CATALOG_TABLE
                );


            if (
                !approvedSkillGR.isValid()
            ) {

                data.actionSuccess = false;

                data.actionMessage =
                    'Skill Catalog table was not found.';

                return;
            }


            /*
             * Search by skill_name.
             * We use case-insensitive comparison in script
             * so SAP and sap will not create duplicates.
             */

            var existingSkillId = '';

            approvedSkillGR.query();

            while (
                approvedSkillGR.next()
            ) {

                var catalogSkillName =
                    String(
                        approvedSkillGR.getValue(
                            'skill_name'
                        ) || ''
                    ).trim();


                if (
                    catalogSkillName.toLowerCase() ===
                    requestedSkillName.toLowerCase()
                ) {

                    existingSkillId =
                        approvedSkillGR.getUniqueValue();

                    break;
                }
            }


            /* -------------------------------------------------
               CREATE NEW SKILL IF IT DOES NOT EXIST
               ------------------------------------------------- */

            if (!existingSkillId) {

                var newSkillGR =
                    new GlideRecord(
                        SKILL_CATALOG_TABLE
                    );

                newSkillGR.initialize();


                if (
                    newSkillGR.isValidField(
                        'skill_name'
                    )
                ) {

                    newSkillGR.setValue(
                        'skill_name',
                        requestedSkillName
                    );

                } else {

                    data.actionSuccess = false;

                    data.actionMessage =
                        'Skill Catalog skill_name field was not found.';

                    return;
                }


                /*
                 * If the Active field exists, make the
                 * newly-created skill active.
                 */

                if (
                    newSkillGR.isValidField(
                        'active'
                    )
                ) {

                    newSkillGR.setValue(
                        'active',
                        true
                    );

                }


                existingSkillId =
                    newSkillGR.insert();


                if (!existingSkillId) {

                    data.actionSuccess = false;

                    data.actionMessage =
                        'Unable to create the new skill in Skill Catalog.';

                    return;
                }
            }


            /* -------------------------------------------------
               ADD SKILL TO STUDENT
               WITHOUT DUPLICATE
               ------------------------------------------------- */

            var approvedCurrentSkills =
                approvedStudentGR.getValue(
                    'skills'
                ) || '';

            var approvedSkillArray =
                approvedCurrentSkills
                    ? approvedCurrentSkills.split(',')
                    : [];


            if (
                approvedSkillArray.indexOf(
                    existingSkillId
                ) < 0
            ) {

                approvedSkillArray.push(
                    existingSkillId
                );

            }


            approvedStudentGR.setValue(
                'skills',
                approvedSkillArray.join(',')
            );


            approvedStudentGR.update();


            /* -------------------------------------------------
               STORE MATCHED SKILL
               ------------------------------------------------- */

            if (
                skillRequestGR.isValidField(
                    'matched_skills'
                )
            ) {

                skillRequestGR.setValue(
                    'matched_skills',
                    existingSkillId
                );

            }


            /* -------------------------------------------------
               UPDATE REQUEST STATUS
               ------------------------------------------------- */

            skillRequestGR.setValue(
                'status',
                'approved'
            );


            if (
                skillRequestGR.isValidField(
                    'reviewed_by'
                )
            ) {

                skillRequestGR.setValue(
                    'reviewed_by',
                    USER_ID
                );

            }


            skillRequestGR.update();


            /* -------------------------------------------------
               SUCCESS
               ------------------------------------------------- */

            data.actionSuccess = true;

            data.actionDecision =
                'approved';

            data.actionSkillRequestId =
                skillRequestId;

            data.actionSkillId =
                existingSkillId;

            data.actionMessage =
                'Skill request approved and skill added to the student successfully.';

            return;
        }


        /* =====================================================
           REJECT
           ===================================================== */

        if (
            skillDecision === 'rejected'
        ) {

            skillRequestGR.setValue(
                'status',
                'rejected'
            );


            if (
                skillRequestGR.isValidField(
                    'reviewed_by'
                )
            ) {

                skillRequestGR.setValue(
                    'reviewed_by',
                    USER_ID
                );

            }


            skillRequestGR.update();


            data.actionSuccess = true;

            data.actionDecision =
                'rejected';

            data.actionSkillRequestId =
                skillRequestId;

            data.actionMessage =
                'Skill request rejected successfully.';

            return;
        }

    }


    /* =========================================================
       PLACEMENT ADMIN
       ========================================================= */

    if (isAdmin) {


        /* -----------------------------------------------------
           NEW APPLICATIONS
           ----------------------------------------------------- */

        var applicationGR =
            new GlideRecord(
                APPLICATION_TABLE
            );

        if (applicationGR.isValid()) {

            applicationGR.orderByDesc(
                'sys_created_on'
            );

            applicationGR.setLimit(20);

            applicationGR.query();


            while (applicationGR.next()) {

                var appDetails =
                    getApplicationDetails(
                        applicationGR
                    );

                var studentName =
                    getStudentName(
                        applicationGR.getValue(
                            'student'
                        )
                    );


                addNotification(

                    'admin_application_' +
                    applicationGR.getUniqueValue(),

                    'application',

                    'New Application',

                    studentName +
                    ' submitted an application for ' +
                    (
                        appDetails.driveName ||
                        'a placement drive'
                    ) +
                    '.',

                    applicationGR.getDisplayValue(
                        'sys_created_on'
                    ),

                    appDetails.company,

                    appDetails.driveName,

                    true,

                    '?id=applications',

                    'View Application',

                    applicationGR.getValue(
                        'sys_created_on'
                    )
                );
            }
        }


        /* -----------------------------------------------------
           PLACEMENT DRIVES
           ----------------------------------------------------- */

        var driveGR =
            new GlideRecord(
                DRIVE_TABLE
            );

        if (driveGR.isValid()) {

            driveGR.orderByDesc(
                'sys_created_on'
            );

            driveGR.setLimit(20);

            driveGR.query();


            while (driveGR.next()) {

                addNotification(

                    'admin_drive_' +
                    driveGR.getUniqueValue(),

                    'drive',

                    'Placement Drive Created',

                    'A new placement drive has been created for ' +
                    (
                        driveGR.getDisplayValue(
                            'company'
                        ) ||
                        'Company'
                    ) +
                    '.',

                    driveGR.getDisplayValue(
                        'sys_created_on'
                    ),

                    driveGR.getDisplayValue(
                        'company'
                    ),

                    driveGR.getDisplayValue(
                        'drive_name'
                    ),

                    true,

                    '?id=placement_drives',

                    'View Drive',

                    driveGR.getValue(
                        'sys_created_on'
                    )
                );
            }
        }


        /* -----------------------------------------------------
           INTERVIEWS REQUIRING ATTENTION
           ----------------------------------------------------- */

        var adminInterviewGR =
            new GlideRecord(
                INTERVIEW_TABLE
            );

        if (adminInterviewGR.isValid()) {

            adminInterviewGR.addQuery(
                'status',
                '!=',
                'Complete'
            );

            adminInterviewGR.orderByDesc(
                'sys_updated_on'
            );

            adminInterviewGR.setLimit(20);

            adminInterviewGR.query();


            while (adminInterviewGR.next()) {

                addNotification(

                    'admin_interview_' +
                    adminInterviewGR.getUniqueValue(),

                    'interview',

                    'Interview Requires Attention',

                    'An interview requires attention.',

                    adminInterviewGR.getDisplayValue(
                        'sys_updated_on'
                    ),

                    adminInterviewGR.getDisplayValue(
                        'company'
                    ),

                    '',

                    true,

                    '?id=interviews',

                    'View Interview',

                    adminInterviewGR.getValue(
                        'sys_updated_on'
                    )
                );
            }
        }


        /* -----------------------------------------------------
           OFFER LETTERS
           ----------------------------------------------------- */

        var adminOfferGR =
            new GlideRecord(
                OFFER_TABLE
            );

        if (adminOfferGR.isValid()) {

            adminOfferGR.orderByDesc(
                'sys_created_on'
            );

            adminOfferGR.setLimit(20);

            adminOfferGR.query();


            while (adminOfferGR.next()) {

                var adminOfferStudent =
                    getStudentName(
                        adminOfferGR.getValue(
                            'student'
                        )
                    );


                addNotification(

                    'admin_offer_' +
                    adminOfferGR.getUniqueValue(),

                    'offer',

                    'Offer Letter Generated',

                    'An offer letter has been generated for ' +
                    adminOfferStudent +
                    '.',

                    adminOfferGR.getDisplayValue(
                        'sys_created_on'
                    ),

                    adminOfferGR.getDisplayValue(
                        'company'
                    ),

                    '',

                    true,

                    '?id=offer_letter',

                    'View Offer',

                    adminOfferGR.getValue(
                        'sys_created_on'
                    )
                );
            }
        }


        /* =====================================================
           SKILL REQUESTS
           PLACEMENT ADMIN / TPO
           ===================================================== */

        var skillRequestListGR =
            new GlideRecord(
                SKILL_REQUEST_TABLE
            );

        if (
            skillRequestListGR.isValid()
        ) {

            skillRequestListGR.addQuery(
                'status',
                'pending'
            );

            skillRequestListGR.orderByDesc(
                'sys_created_on'
            );

            skillRequestListGR.setLimit(30);

            skillRequestListGR.query();


            while (
                skillRequestListGR.next()
            ) {

                var requestedStudentId =
                    skillRequestListGR.getValue(
                        'requested_by'
                    );

                var requestedStudentName =
                    getStudentName(
                        requestedStudentId
                    );


                var requestedSkill =
                    skillRequestListGR.getValue(
                        'requested_term'
                    ) || 'New Skill';


                var skillRequestNotificationId =
                    'skill_request_' +
                    skillRequestListGR.getUniqueValue();


                addNotification(

                    skillRequestNotificationId,

                    'skill_request',

                    'New Skill Request',

                    requestedStudentName +
                    ' requested a new skill: ' +
                    requestedSkill +
                    '.',

                    skillRequestListGR.getDisplayValue(
                        'sys_created_on'
                    ),

                    '',

                    '',

                    true,

                    '',

                    '',

                    skillRequestListGR.getValue(
                        'sys_created_on'
                    )
                );


                var skillNotification =
                    data.notifications[
                        data.notifications.length - 1
                    ];


                skillNotification.skillRequestId =
                    skillRequestListGR.getUniqueValue();

                skillNotification.skillRequestDecision =
                    'pending';

                skillNotification.canDecide =
                    true;

                skillNotification.showSkillMap =
                    false;

                skillNotification.selectedSkillId =
                    '';


                /* -------------------------------------------------
                   GET EXISTING SKILLS FOR MAP EXISTING
                   ------------------------------------------------- */

                skillNotification.skillOptions = [];


                var skillCatalogGR =
                    new GlideRecord(
                        SKILL_CATALOG_TABLE
                    );

                if (
                    skillCatalogGR.isValid()
                ) {

                    /*
                     * Use the actual Skill Catalog field:
                     * skill_name
                     */

                    skillCatalogGR.orderBy(
                        'skill_name'
                    );

                    skillCatalogGR.setLimit(100);

                    skillCatalogGR.query();


                    while (
                        skillCatalogGR.next()
                    ) {

                        skillNotification.skillOptions
                            .push({

                                id:
                                    skillCatalogGR
                                    .getUniqueValue(),

                                name:
                                    skillCatalogGR
                                    .getValue(
                                        'skill_name'
                                    ) ||
                                    skillCatalogGR
                                    .getDisplayValue()

                            });
                    }
                }
            }
        }


        sortNotifications();

        return;
    }


    /* =========================================================
       PLACEMENT OFFICER
       ========================================================= */

    if (isOfficer) {


        /* -----------------------------------------------------
           APPLICATIONS
           ----------------------------------------------------- */

        var officerApplicationGR =
            new GlideRecord(
                APPLICATION_TABLE
            );

        if (
            officerApplicationGR.isValid()
        ) {

            officerApplicationGR.orderByDesc(
                'sys_created_on'
            );

            officerApplicationGR.setLimit(20);

            officerApplicationGR.query();


            while (
                officerApplicationGR.next()
            ) {

                var officerAppDetails =
                    getApplicationDetails(
                        officerApplicationGR
                    );

                var officerStudent =
                    getStudentName(
                        officerApplicationGR.getValue(
                            'student'
                        )
                    );


                addNotification(

                    'officer_application_' +
                    officerApplicationGR.getUniqueValue(),

                    'application',

                    'New Application',

                    officerStudent +
                    ' submitted an application.',

                    officerApplicationGR.getDisplayValue(
                        'sys_created_on'
                    ),

                    officerAppDetails.company,

                    officerAppDetails.driveName,

                    true,

                    '?id=applications',

                    'View Application',

                    officerApplicationGR.getValue(
                        'sys_created_on'
                    )
                );
            }
        }


        /* -----------------------------------------------------
           PLACEMENT DRIVES
           ----------------------------------------------------- */

        var officerDriveGR =
            new GlideRecord(
                DRIVE_TABLE
            );

        if (
            officerDriveGR.isValid()
        ) {

            officerDriveGR.orderByDesc(
                'sys_created_on'
            );

            officerDriveGR.setLimit(20);

            officerDriveGR.query();


            while (
                officerDriveGR.next()
            ) {

                addNotification(

                    'officer_drive_' +
                    officerDriveGR.getUniqueValue(),

                    'drive',

                    'Placement Drive',

                    'A placement drive has been created.',

                    officerDriveGR.getDisplayValue(
                        'sys_created_on'
                    ),

                    officerDriveGR.getDisplayValue(
                        'company'
                    ),

                    officerDriveGR.getDisplayValue(
                        'drive_name'
                    ),

                    true,

                    '?id=placement_drives',

                    'View Drive',

                    officerDriveGR.getValue(
                        'sys_created_on'
                    )
                );
            }
        }


        sortNotifications();

        return;
    }


    /* =========================================================
       INTERVIEWER / COMPANY HR
       ========================================================= */

    if (isInterviewer) {

        var companyIds = [];


        /* -----------------------------------------------------
           GET COMPANIES FOR CURRENT HR
           ----------------------------------------------------- */

        var hrCompanyGR =
            new GlideRecord(
                COMPANY_TABLE
            );

        if (hrCompanyGR.isValid()) {

            hrCompanyGR.addQuery(
                'hr_user',
                USER_ID
            );

            hrCompanyGR.query();


            while (
                hrCompanyGR.next()
            ) {

                companyIds.push(
                    hrCompanyGR.getUniqueValue()
                );
            }
        }


        /* -----------------------------------------------------
           OFFER LETTERS FOR COMPANY
           ----------------------------------------------------- */

        if (companyIds.length > 0) {

            var interviewerOfferGR =
                new GlideRecord(
                    OFFER_TABLE
                );

            if (
                interviewerOfferGR.isValid()
            ) {

                interviewerOfferGR.addQuery(
                    'company',
                    'IN',
                    companyIds.join(',')
                );

                interviewerOfferGR.orderByDesc(
                    'sys_created_on'
                );

                interviewerOfferGR.setLimit(30);

                interviewerOfferGR.query();


                while (
                    interviewerOfferGR.next()
                ) {

                    var oldOfferStudent =
                        getStudentName(
                            interviewerOfferGR.getValue(
                                'student'
                            )
                        );

                    var oldOfferCompany =
                        interviewerOfferGR.getDisplayValue(
                            'company'
                        ) || 'Company';


                    addNotification(

                        'offer_' +
                        interviewerOfferGR.getUniqueValue(),

                        'offer',

                        'Offer Letter Created',

                        'An offer letter has been created for ' +
                        oldOfferStudent +
                        ' at ' +
                        oldOfferCompany +
                        '.',

                        interviewerOfferGR.getDisplayValue(
                            'sys_created_on'
                        ),

                        oldOfferCompany,

                        '',

                        true,

                        '?id=offer_letter',

                        'View Offer',

                        interviewerOfferGR.getValue(
                            'sys_created_on'
                        )
                    );
                }
            }
        }


        /* -----------------------------------------------------
           GET PENDING OFFER LETTER APPROVALS
           ----------------------------------------------------- */

        if (companyIds.length > 0) {

            var approvalGR =
                new GlideRecord(
                    OFFER_APPROVAL_TABLE
                );

            if (approvalGR.isValid()) {

                approvalGR.addQuery(
                    'hr_user',
                    USER_ID
                );

                approvalGR.addQuery(
                    'decision',
                    'pending'
                );

                approvalGR.orderByDesc(
                    'sys_created_on'
                );

                approvalGR.setLimit(30);

                approvalGR.query();


                while (
                    approvalGR.next()
                ) {

                    var approvalOfferId =
                        approvalGR.getValue(
                            'offer_letter'
                        );

                    if (!approvalOfferId) {
                        continue;
                    }


                    var approvalOfferGR =
                        new GlideRecord(
                            OFFER_TABLE
                        );

                    if (
                        !approvalOfferGR.get(
                            approvalOfferId
                        )
                    ) {
                        continue;
                    }


                    var approvalCompanyId =
                        approvalOfferGR.getValue(
                            'company'
                        );


                    if (
                        !approvalCompanyId ||
                        companyIds.indexOf(
                            approvalCompanyId
                        ) < 0
                    ) {
                        continue;
                    }


                    var approvalStudent =
                        getStudentName(
                            approvalOfferGR.getValue(
                                'student'
                            )
                        );


                    var approvalCompany =
                        approvalOfferGR.getDisplayValue(
                            'company'
                        ) || 'Company';


                    addNotification(

                        'offer_approval_' +
                        approvalGR.getUniqueValue(),

                        'offer_approval',

                        'Offer Letter Requires Your Review',

                        'A new offer letter has been created for ' +
                        approvalStudent +
                        ' at ' +
                        approvalCompany +
                        '. Please accept or reject the offer.',

                        approvalGR.getDisplayValue(
                            'sys_created_on'
                        ),

                        approvalCompany,

                        '',

                        true,

                        '',

                        '',

                        approvalGR.getValue(
                            'sys_created_on'
                        )
                    );


                    var latestNotification =
                        data.notifications[
                            data.notifications.length - 1
                        ];


                    latestNotification.approvalId =
                        approvalGR.getUniqueValue();

                    latestNotification.offerLetterId =
                        approvalOfferId;

                    latestNotification.decision =
                        'pending';

                    latestNotification.canDecide =
                        true;
                }
            }
        }


        sortNotifications();

        return;
    }


    /* =========================================================
       STUDENT
       ========================================================= */

    var studentGR =
        new GlideRecord(
            STUDENT_TABLE
        );

    if (!studentGR.isValid()) {

        data.error =
            'Student table was not found.';

        return;
    }


    studentGR.addQuery(
        'user',
        USER_ID
    );

    studentGR.setLimit(1);

    studentGR.query();


    if (!studentGR.next()) {

        data.error =
            'Student profile not found.';

        return;
    }


    var studentId =
        studentGR.getUniqueValue();


    /* =========================================================
       STUDENT APPLICATIONS
       ========================================================= */

    var studentApplicationGR =
        new GlideRecord(
            APPLICATION_TABLE
        );

    if (
        studentApplicationGR.isValid()
    ) {

        studentApplicationGR.addQuery(
            'student',
            studentId
        );

        studentApplicationGR.orderByDesc(
            'sys_created_on'
        );

        studentApplicationGR.setLimit(30);

        studentApplicationGR.query();


        while (
            studentApplicationGR.next()
        ) {

            var studentAppDetails =
                getApplicationDetails(
                    studentApplicationGR
                );


            var applicationStatus =
                studentApplicationGR.getDisplayValue(
                    'status'
                ) || '';


            addNotification(

                'student_application_' +
                studentApplicationGR.getUniqueValue(),

                'application',

                'Application Update',

                'Your application status is ' +
                applicationStatus +
                '.',


                studentApplicationGR.getDisplayValue(
                    'sys_updated_on'
                ),


                studentAppDetails.company,


                studentAppDetails.driveName,


                true,


                '?id=applications',


                'View Application',


                studentApplicationGR.getValue(
                    'sys_updated_on'
                )
            );
        }
    }


    /* =========================================================
       STUDENT OFFER LETTERS
       ========================================================= */

    var studentOfferGR =
        new GlideRecord(
            OFFER_TABLE
        );

    if (
        studentOfferGR.isValid()
    ) {

        studentOfferGR.addQuery(
            'student',
            studentId
        );

        studentOfferGR.orderByDesc(
            'sys_created_on'
        );

        studentOfferGR.setLimit(20);

        studentOfferGR.query();


        while (
            studentOfferGR.next()
        ) {

            var studentOfferCompany =
                studentOfferGR.getDisplayValue(
                    'company'
                ) || 'Company';


            addNotification(

                'student_offer_' +
                studentOfferGR.getUniqueValue(),

                'offer',

                'Offer Letter Available',

                'Your offer letter from ' +
                studentOfferCompany +
                ' is available.',

                studentOfferGR.getDisplayValue(
                    'sys_created_on'
                ),

                studentOfferCompany,

                '',

                true,

                '?id=offer_letter',

                'View Offer',

                studentOfferGR.getValue(
                    'sys_created_on'
                )
            );
        }
    }


    /* =========================================================
       UPCOMING PLACEMENT DRIVES
       ========================================================= */

    var studentDriveGR =
        new GlideRecord(
            DRIVE_TABLE
        );

    if (
        studentDriveGR.isValid()
    ) {

        studentDriveGR.orderByDesc(
            'sys_created_on'
        );

        studentDriveGR.setLimit(20);

        studentDriveGR.query();


        while (
            studentDriveGR.next()
        ) {

            addNotification(

                'student_drive_' +
                studentDriveGR.getUniqueValue(),

                'drive',

                'Placement Drive',

                'A placement drive is available from ' +
                (
                    studentDriveGR.getDisplayValue(
                        'company'
                    ) || 'Company'
                ) +
                '.',

                studentDriveGR.getDisplayValue(
                    'sys_created_on'
                ),

                studentDriveGR.getDisplayValue(
                    'company'
                ),

                studentDriveGR.getDisplayValue(
                    'drive_name'
                ),

                true,

                '?id=placement_drives',

                'View Drive',

                studentDriveGR.getValue(
                    'sys_created_on'
                )
            );
        }
    }


    /* =========================================================
       FINAL SORT
       ========================================================= */

    sortNotifications();


    if (
        data.notifications.length > 50
    ) {

        data.notifications =
            data.notifications.slice(
                0,
                50
            );
    }

})();
